-- KẾT QUẢ KIỂM TRA / TRA CỨU SAU CÀI ĐẶT
SELECT N'46 bảng, 457 dòng' AS KetQua, COUNT(*) AS SoBang FROM sys.tables WHERE is_ms_shipped=0;
